//     .font(.ripul(.caption, family: .code))        was .font(.caption.monospaced())
//     .font(.ripul(size: 14, weight: .medium))      was .font(.system(size: 14, weight: .medium))
//     .font(.ripulIcon(size: 18))                   was .font(.system(size: 18)) on an Image
//
